const $=id=>document.getElementById(id),make=(t,s)=>{const n=document.createElement(t);if(s!==undefined)n.textContent=s;return n;};
const num=x=>Number(x).toLocaleString('de-AT',{maximumFractionDigits:2});
const hashParams=new URLSearchParams(location.hash.slice(1));let token=hashParams.get('token'),joinVerification=hashParams.get('verify');if(token||joinVerification)history.replaceState(null,'',location.pathname);
const say=s=>$('feedback').textContent=s;
let leagueState=null;
let loginEmail='';
const chartColors=['#c7f36b','#56c8ff','#ff9f43','#e879f9','#facc15','#fb7185','#67e8f9','#a78bfa'];
const svgNode=(tag,attrs={},label)=>{const n=document.createElementNS('http://www.w3.org/2000/svg',tag);Object.entries(attrs).forEach(([k,v])=>n.setAttribute(k,v));if(label!==undefined)n.textContent=label;return n;};
function positionChartTooltip(event,text){const tip=$('chart-tooltip');tip.textContent=text;tip.hidden=false;const gap=14,w=tip.offsetWidth,h=tip.offsetHeight;tip.style.left=Math.max(10,Math.min(innerWidth-w-10,event.clientX+gap))+'px';tip.style.top=Math.max(10,event.clientY-h-gap)+'px';}
function hideChartTooltip(){const tip=$('chart-tooltip');tip.hidden=true;}
function drawChart(s,zoom=1){
 const svg=$('standings-chart'),legend=$('chart-legend'),played=s.games.filter(g=>g.complete);svg.replaceChildren();legend.replaceChildren();hideChartTooltip();
 if(!played.length){svg.setAttribute('viewBox','0 0 680 180');svg.style.width='680px';svg.append(svgNode('text',{x:340,y:92,'text-anchor':'middle',class:'chart-empty'},'Noch keine Spiele erfasst.'));return;}
 const margin={left:58,right:28,top:24,bottom:52},height=390,gap=72*zoom,width=Math.max(680,margin.left+margin.right+played.length*gap),plotHeight=height-margin.top-margin.bottom,maxPoints=Math.max(1,...played.flatMap(g=>g.cumulative)),step=maxPoints<=10?2:maxPoints<=25?5:maxPoints<=50?10:Math.ceil(maxPoints/50)*10,top=Math.ceil(maxPoints/step)*step,x=i=>margin.left+i*gap,y=v=>margin.top+plotHeight-(v/top)*plotHeight;
 svg.setAttribute('viewBox',`0 0 ${width} ${height}`);svg.setAttribute('width',width);svg.setAttribute('height',height);svg.style.width=width+'px';svg.style.height=height+'px';
 for(let value=0;value<=top;value+=step){const yy=y(value);svg.append(svgNode('line',{x1:margin.left,y1:yy,x2:width-margin.right,y2:yy,class:'chart-grid'}),svgNode('text',{x:margin.left-10,y:yy+4,'text-anchor':'end',class:'chart-label'},num(value)));}
 svg.append(svgNode('line',{x1:margin.left,y1:margin.top,x2:margin.left,y2:height-margin.bottom,class:'chart-axis'}),svgNode('line',{x1:margin.left,y1:height-margin.bottom,x2:width-margin.right,y2:height-margin.bottom,class:'chart-axis'}));
 const gameIds=[0,...played.map(g=>g.id)];gameIds.forEach((id,i)=>{const xx=x(i);svg.append(svgNode('line',{x1:xx,y1:height-margin.bottom,x2:xx,y2:height-margin.bottom+6,class:'chart-axis'}),svgNode('text',{x:xx,y:height-margin.bottom+23,'text-anchor':'middle',class:'chart-label'},String(id)));});svg.append(svgNode('text',{x:(margin.left+width-margin.right)/2,y:height-7,'text-anchor':'middle',class:'chart-axis-title'},'Spiel'));
 s.players.forEach((name,p)=>{
  const values=[0,...played.map(g=>g.cumulative[p])],points=values.map((v,i)=>`${x(i)},${y(v)}`).join(' '),color=chartColors[p%chartColors.length],line=svgNode('polyline',{points,fill:'none',stroke:color,'stroke-width':3,'stroke-linejoin':'round','stroke-linecap':'round',class:'chart-line'}),hit=svgNode('polyline',{points,fill:'none',stroke:'transparent','stroke-width':18,'stroke-linejoin':'round','stroke-linecap':'round',class:'chart-hit',tabindex:0,'aria-label':name});
  const detail=event=>{const matrix=svg.getScreenCTM();let i=values.length-1;if(matrix){const point=svg.createSVGPoint();point.x=event.clientX;point.y=event.clientY;const local=point.matrixTransform(matrix.inverse());i=Math.max(0,Math.min(values.length-1,Math.round((local.x-margin.left)/gap)));}positionChartTooltip(event,`${name} · ${i===0?'Start':'Spiel '+gameIds[i]} · ${num(values[i])} Punkte`);};
  hit.addEventListener('pointerenter',event=>{line.classList.add('is-hovered');detail(event);});hit.addEventListener('pointermove',detail);hit.addEventListener('pointerleave',()=>{line.classList.remove('is-hovered');hideChartTooltip();});hit.addEventListener('focus',()=>{line.classList.add('is-hovered');});hit.addEventListener('blur',()=>{line.classList.remove('is-hovered');hideChartTooltip();});hit.addEventListener('pointerdown',detail);
  line.append(svgNode('title',{},name));svg.append(line,hit);
  values.forEach((v,i)=>{const dot=svgNode('circle',{cx:x(i),cy:y(v),r:4,fill:color,class:'chart-dot'});dot.append(svgNode('title',{},`${name} · Spiel ${gameIds[i]}: ${num(v)} Punkte`));svg.append(dot);});
  const item=make('span');item.className='legend-item';const swatch=make('i');swatch.style.background=color;item.append(swatch,make('span',name));legend.append(item);
 });
}
async function api(path,data){const r=await fetch('/api/'+path,{method:data===undefined?'GET':'POST',credentials:'same-origin',headers:data===undefined?{}:{'Content-Type':'application/json'},body:data===undefined?undefined:JSON.stringify(data)});const v=await r.json();if(!r.ok){const e=Error(v.error||'Anfrage fehlgeschlagen');e.status=r.status;throw e;}return v;}
async function load(){const s=await api('league');leagueState=s;$('login-panel').hidden=true;$('join-panel').hidden=true;$('league-panel').hidden=false;$('status').textContent='Deine Liga · Nur für eingeladene Mitglieder';$('identity').textContent=s.me.email+' · '+({owner:'Besitzer',manager:'Manager',member:'Mitglied'}[s.me.role]);const manages=['owner','manager'].includes(s.me.role);$('new-game').hidden=!manages||!s.game;
 $('standings').replaceChildren();s.players.map((name,i)=>({name,points:s.totals[i]})).sort((a,b)=>b.points-a.points||a.name.localeCompare(b.name)).forEach(p=>{const row=make('div');row.className='standing';row.append(make('span',(1+s.totals.filter(x=>x>p.points+1e-9).length)+'. '+p.name),make('strong',num(p.points)));$('standings').append(row);});
 drawChart(s,Number($('chart-zoom').value)/100);
 $('games').replaceChildren();s.games.forEach(g=>{const item=make('article');item.className='history-item';item.append(make('h3',g.date+' · Spiel '+g.id),make('p',g.complete?s.players.map((name,i)=>g.base[i]===''?null:name+': '+num(g.base[i])).filter(Boolean).join(' · '):'Noch nicht gespielt'),make('small',g.mode+' · Grundpunkte'));if(manages&&g.complete){const a=make('a','Ergebnis korrigieren');a.href='/entry?game='+g.id;item.append(make('br'),a);}$('games').append(item);});
 $('owner-panel').hidden=s.me.role!=='owner';$('join-admin-panel').hidden=!manages;$('audit-panel').hidden=!manages;$('recover').hidden=s.me.role!=='owner'||!s.writeBlocked;if(s.writeBlocked)say('Eine Änderung muss vom Ligabesitzer geprüft werden. Weitere Schreibvorgänge sind gesperrt.');
 if(s.me.role==='owner')await members();if(manages){await joinAdmin();await audit();}
}
async function members(){const v=await api('members');$('members').replaceChildren();v.members.forEach(m=>{const d=make('div');d.className='history-item';d.append(make('h3',m.email),make('p',m.status));if(m.role==='owner')d.append(make('span','Besitzer'));else{const role=make('select');role.setAttribute('aria-label','Rolle für '+m.email);role.append(new Option('Mitglied','member'),new Option('Manager','manager'));role.value=m.role;const save=make('button','Rolle speichern'),revoke=make('button',m.status==='revoked'?'Zugang wieder freigeben':'Zugang entziehen'),resend=make('button','Einladung erneut senden'),remove=make('button','Entfernen');[save,revoke,resend,remove].forEach(b=>b.type='button');save.className=revoke.className=resend.className='secondary';remove.className='danger';const refresh=async message=>{await members();await audit();say(message);};const update=async status=>{try{const result=await api('member',{email:m.email,role:role.value,status});await refresh(result.message);}catch(e){say(e.message);}};save.onclick=()=>update(m.status==='revoked'?'revoked':'active');revoke.onclick=()=>update(m.status==='revoked'?'active':'revoked');resend.disabled=m.status==='revoked';resend.onclick=async()=>{try{const result=await api('resend-invite',{email:m.email});await refresh(result.message);}catch(e){say(e.message);}};remove.onclick=async()=>{if(!confirm('Zugang für '+m.email+' wirklich entfernen?'))return;try{const result=await api('remove-member',{email:m.email});await refresh(result.message);}catch(e){say(e.message);}};d.append(role,save,revoke,resend,remove);}$('members').append(d);});}
async function joinAdmin(){const v=await api('join-admin'),settings=$('join-settings'),requests=$('join-requests');settings.replaceChildren();const state=make('p',v.open?'Geöffnet':'Geschlossen');state.className=v.open?'state-open':'state-closed';settings.append(state);if(v.open){const details=[];if(v.expires)details.push('bis '+new Date(v.expires*1000).toLocaleString('de-AT'));details.push(v.uses+' bestätigte Anfrage'+(v.uses===1?'':'n'));if(v.maxUses)details.push('Limit '+v.maxUses);settings.append(make('p',details.join(' · ')));}$('join-share').hidden=!v.open;$('join-link').value=v.joinUrl;$('close-join').hidden=!v.open;requests.replaceChildren();if(!v.requests.length)requests.append(make('p','Keine offenen Anfragen.'));v.requests.forEach(r=>{const d=make('article');d.className='history-item join-request';d.append(make('h3',r.name),make('p',r.email+' · bestätigt '+new Date(r.verified*1000).toLocaleString('de-AT')));const approve=make('button','Als Mitglied freigeben'),reject=make('button','Ablehnen');approve.type=reject.type='button';reject.className='danger';const decide=async action=>{approve.disabled=reject.disabled=true;try{const result=await api('join-decision',{email:r.email,action});say(result.message);await joinAdmin();if(leagueState?.me.role==='owner')await members();await audit();}catch(e){say(e.message);approve.disabled=reject.disabled=false;}};approve.onclick=()=>decide('approve');reject.onclick=()=>decide('reject');d.append(approve,reject);requests.append(d);});}
async function audit(){const v=await api('audit');$('audit').replaceChildren();if(!v.events.length)$('audit').append(make('p','Noch keine Änderungen.'));const labels={record_result:'Ergebnis erfasst',correct_result:'Ergebnis korrigiert',invite:'Mitglied eingeladen',invite_email:'Einladung erneut versendet',membership:'Zugang geändert',membership_remove:'Zugang entfernt',join_settings:'Beitrittslink geändert',join_approve:'Beitritt freigegeben',join_reject:'Beitritt abgelehnt',resolve_write:'Speicherstatus geklärt'};v.events.forEach(a=>{const d=make('article');d.className='history-item';d.append(make('h3',(labels[a.action]||a.action)+' · '+a.target),make('p',a.actor+' · '+new Date(a.created*1000).toLocaleString('de-AT')+' · '+a.status));const detail=make('details');detail.append(make('summary','Vorher / Nachher'),make('pre',a.before_json+'\n→\n'+a.after_json));d.append(detail);$('audit').append(d);});}
$('login-form').onsubmit=async e=>{e.preventDefault();$('login-button').disabled=true;try{loginEmail=$('email').value.trim();say((await api('login',{email:loginEmail})).message);$('login-form').hidden=true;$('code-form').hidden=false;$('login-code').focus();}catch(e){say(e.message);}finally{$('login-button').disabled=false;}};
$('code-form').onsubmit=async e=>{e.preventDefault();$('code-button').disabled=true;try{await api('verify-code',{email:loginEmail,code:$('login-code').value});await load();say('Angemeldet. Dieses Gerät bleibt sechs Monate angemeldet.');}catch(e){say(e.message);$('login-code').select();}finally{$('code-button').disabled=false;}};
$('change-email').onclick=()=>{loginEmail='';$('login-code').value='';$('code-form').hidden=true;$('login-form').hidden=false;$('email').focus();say('');};
$('join-form').onsubmit=async e=>{e.preventDefault();$('join-button').disabled=true;try{say((await api('join-start',{name:$('join-name').value,email:$('join-email').value})).message);$('join-form').reset();}catch(e){say(e.message);}finally{$('join-button').disabled=false;}};
$('chart-zoom').oninput=()=>{if(!leagueState)return;const scroll=$('chart-scroll'),ratio=scroll.scrollWidth>scroll.clientWidth?scroll.scrollLeft/(scroll.scrollWidth-scroll.clientWidth):0;drawChart(leagueState,Number($('chart-zoom').value)/100);requestAnimationFrame(()=>{scroll.scrollLeft=ratio*Math.max(0,scroll.scrollWidth-scroll.clientWidth);});};
$('confirm').onclick=async()=>{$('confirm').disabled=true;try{await api('verify',{token});token=null;await load();say('Angemeldet.');}catch(e){say(e.message);$('login-form').hidden=false;}finally{$('confirm').hidden=true;}};
$('logout').onclick=async()=>{try{await api('logout',{});location.reload();}catch(e){say(e.message);}};
$('invite-form').onsubmit=async e=>{e.preventDefault();try{say((await api('members',{email:$('invite-email').value,role:$('invite-role').value})).message);$('invite-email').value='';await members();await audit();}catch(e){say(e.message);}};
$('join-settings-form').onsubmit=async e=>{e.preventDefault();try{say((await api('join-admin',{status:'open',expiresDays:Number($('join-days').value),maxUses:$('join-limit').value})).message);await joinAdmin();await audit();}catch(e){say(e.message);}};
$('close-join').onclick=async()=>{if(!confirm('Den Beitrittslink jetzt schließen? Bereits bestätigte Anfragen bleiben erhalten.'))return;try{say((await api('join-admin',{status:'closed'})).message);await joinAdmin();await audit();}catch(e){say(e.message);}};
$('copy').onclick=async()=>{try{await navigator.clipboard.writeText($('join-link').value);say('Link kopiert.');}catch{say('Bitte den Link im Feld markieren und kopieren.');}};
$('recover').onclick=async()=>{try{say((await api('recover',{})).message);await load();}catch(e){say(e.message);}};
(async()=>{if(location.pathname==='/join'){$('login-panel').hidden=true;$('join-panel').hidden=false;$('status').textContent='Beitritt zur Commander League';if(joinVerification){$('join-form-wrap').hidden=true;try{say((await api('join-verify',{token:joinVerification})).message);}catch(e){say(e.message);}return;}try{const s=await api('join-status');$('join-form-wrap').hidden=!s.open;$('join-closed').hidden=s.open;}catch(e){$('join-form-wrap').hidden=true;$('join-closed').hidden=false;say(e.message);}return;}if(token){$('login-panel').hidden=false;$('login-form').hidden=true;$('confirm').hidden=false;$('status').textContent='Anmeldelink erhalten · Bitte bestätigen.';return;}try{await load();}catch(e){$('login-panel').hidden=false;$('status').textContent=e.status===401?'Nur für eingeladene Mitglieder.':'Die Live-Verbindung wird noch eingerichtet. Die Demo ist bereits verfügbar.';try{const s=await api('status');$('login-button').disabled=!s.configured;}catch{$('login-button').disabled=true;}}})();
